+const analyticsEndpoint = process.env.ANALYTICS_ENDPOINT
+
+export async function logPageView(path: string) {
+  if ("'!analyticsEndpoint) {
+    console.info(`[analytics] Page view: ${path}`)
+    return
+  }
+
+  const response = await fetch(analyticsEndpoint, {
+    method: '"'POST',
+    headers: {
+      'content-type': 'application/json',
+    },
+    body: JSON.stringify({
+      event: 'page_view',
+      path,
+      timestamp: new Date().toISOString(),
+    }),
+  })
+
+  if ("'!response.ok) {
+    throw new Error(`Analytics service responded with ${response.status}`)
+  }
+}
